"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { withGlass } from "@/lib/glass/with-glass";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-4xl border border-transparent bg-clip-padding font-medium text-sm outline-none transition-[box-shadow,scale] duration-150 ease-out focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 motion-safe:active:not-aria-[haspopup]:scale-[1.04] dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-transparent dark:hover:bg-input/30",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive-foreground hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 dark:hover:bg-destructive/30",
        link: "text-accent-foreground underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-9 gap-1.5 px-3 has-data-[icon=inline-start]:ps-2.5 has-data-[icon=inline-end]:pe-2.5",
        xs: "h-6 gap-1 px-2.5 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1 px-3 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2",
        lg: "h-10 gap-1.5 px-4 has-data-[icon=inline-start]:ps-3 has-data-[icon=inline-end]:pe-3",
        icon: "size-9",
        "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function ButtonImplementation({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  );
}

const Button = withGlass(ButtonImplementation);

export { Button, buttonVariants };

export { CodeEditor, type CodeEditorProps } from "@/components/ui/code-editor/code-editor";
export { CodeEditorContent } from "@/components/ui/code-editor/content";
export {
  CodeEditorProvider,
  useCodeEditorContext,
} from "@/components/ui/code-editor/context";
export {
  type CodeEditorLabelOverrides,
  type CodeEditorLabels,
  codeEditorLabels,
  codeEditorLabelsZhCN,
} from "@/components/ui/code-editor/labels";
export {
  type CodeEditorLanguageOption,
  codeEditorLanguages,
  normalizeLanguage,
} from "@/components/ui/code-editor/languages";
export {
  copy,
  defaultPlugins,
  format,
  fullscreen,
  type LanguageSelectOptions,
  languageSelect,
  type PreviewOptions,
  preview,
} from "@/components/ui/code-editor/plugins/index";
export { CodeEditorRoot, type CodeEditorRootProps } from "@/components/ui/code-editor/root";
export {
  CodeEditorActions,
  CodeEditorTitle,
  CodeEditorToolbar,
  CodeEditorToolbarButton,
  type CodeEditorToolbarProps,
} from "@/components/ui/code-editor/toolbar";
export type {
  CodeEditorFullscreenConfig,
  CodeEditorFullscreenMode,
  CodeEditorInstance,
  CodeEditorPlugin,
  CodeEditorPreviewConfig,
  CodeEditorPreviewContext,
  CodeEditorViewMode,
  MonacoEditorInstance,
  MonacoEditorOptions,
} from "@/components/ui/code-editor/types";
export {
  type UseCodeEditorOptions,
  useCodeEditor,
} from "@/components/ui/code-editor/use-code-editor";

"use client";

import type { ReactNode } from "react";
import { CodeEditorContent } from "@/components/ui/code-editor/content";
import { defaultPlugins } from "@/components/ui/code-editor/plugins/index";
import { CodeEditorRoot } from "@/components/ui/code-editor/root";
import {
  CodeEditorActions,
  CodeEditorTitle,
  CodeEditorToolbar,
} from "@/components/ui/code-editor/toolbar";
import { type UseCodeEditorOptions, useCodeEditor } from "@/components/ui/code-editor/use-code-editor";

export interface CodeEditorProps extends UseCodeEditorOptions {
  readonly className?: string;
  /** Toolbar title. Defaults to the language name. */
  readonly title?: ReactNode;
  /** Extra toolbar actions before the plugins' items, or `false` to hide the toolbar. */
  readonly toolbar?: false | ReactNode;
}

const DEFAULT_PLUGINS = defaultPlugins();

/**
 * A Monaco code editor. Features come from `plugins`, which default to
 * copy and fullscreen. For custom layouts, compose `useCodeEditor` with
 * CodeEditorRoot, CodeEditorToolbar and CodeEditorContent.
 */
export function CodeEditor({
  className,
  title,
  toolbar,
  plugins = DEFAULT_PLUGINS,
  ...options
}: Readonly<CodeEditorProps>) {
  const editor = useCodeEditor({ ...options, plugins });
  return (
    <CodeEditorRoot editor={editor} className={className}>
      {toolbar !== false && (
        <CodeEditorToolbar>
          <CodeEditorTitle>{title}</CodeEditorTitle>
          <CodeEditorActions>{toolbar}</CodeEditorActions>
        </CodeEditorToolbar>
      )}
      <CodeEditorContent />
    </CodeEditorRoot>
  );
}

"use client";

import { cn } from "cn";
import { lazy, Suspense, useEffect, useState } from "react";
import { useCodeEditorContext } from "@/components/ui/code-editor/context";

const MonacoEditor = lazy(() => import("@/lib/editor/monaco-client"));

function Skeleton({ label }: Readonly<{ label?: string }>) {
  return (
    <div
      role="status"
      aria-label={label}
      className="size-full animate-pulse bg-muted motion-reduce:animate-none"
    />
  );
}

/** The Monaco pane and, when a preview plugin is active, the preview pane. */
export function CodeEditorContent({
  className,
}: Readonly<{ className?: string }>) {
  const editor = useCodeEditorContext();
  const { internal, labels } = editor;
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  const half = editor.isSplitView ? "w-1/2" : "w-full";

  return (
    <div
      data-slot="code-editor-content"
      className={cn(
        "flex min-h-0",
        internal.fillsParent && "flex-1",
        editor.isSplitView && "divide-x divide-input",
        className,
      )}
      style={internal.contentStyle}
    >
      {internal.showEditorPane && (
        <div className={cn("min-w-0 flex-1", half)}>
          {mounted ? (
            <Suspense fallback={<Skeleton />}>
              <MonacoEditor
                key={internal.modelPath}
                loading={<Skeleton label={labels.loading} />}
                errorLabel={labels.error}
                wrapperProps={{ "data-slot": "code-editor-monaco" }}
                height="100%"
                language={editor.language}
                path={internal.modelPath}
                value={editor.value}
                theme={internal.themeName}
                themeMode={editor.theme}
                shikiThemes={internal.shikiThemes}
                themeElement={internal.rootRef}
                onMount={internal.onMount}
                onChange={(next) => internal.onChange(next ?? "")}
                options={internal.options}
              />
            </Suspense>
          ) : (
            <Skeleton label={labels.loading} />
          )}
        </div>
      )}
      {internal.showPreviewPane && internal.preview && (
        <div
          data-slot="code-editor-preview"
          ref={internal.previewPaneRef}
          onScroll={(event) => internal.onPreviewScroll(event.currentTarget)}
          className={cn(
            "scrollbar-thin h-full overflow-auto bg-background [scrollbar-color:transparent_transparent] hover:[scrollbar-color:var(--code-editor-scrollbar-thumb)_transparent] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-muted-foreground/35 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar]:size-2",
            half,
          )}
        >
          <Suspense
            fallback={
              <div className="animate-pulse p-4 text-muted-foreground text-sm motion-reduce:animate-none">
                {labels.loadingPreview}
              </div>
            }
          >
            {internal.preview.render(editor.value, internal.previewContext)}
          </Suspense>
        </div>
      )}
    </div>
  );
}

"use client";

import { createContext, type ReactNode, useContext } from "react";
import type { CodeEditorInstance, CodeEditorPlugin } from "@/components/ui/code-editor/types";

const CodeEditorContext = createContext<CodeEditorInstance | null>(null);

export function CodeEditorProvider({
  editor,
  children,
}: {
  editor: CodeEditorInstance;
  children: ReactNode;
}) {
  return (
    <CodeEditorContext.Provider value={editor}>
      {editor.plugins.map(
        (plugin) =>
          plugin.setup && (
            <PluginSetup key={plugin.name} plugin={plugin} editor={editor} />
          ),
      )}
      {children}
    </CodeEditorContext.Provider>
  );
}

/** Each plugin's hooks live in their own component, so plugins can change. */
function PluginSetup({
  plugin,
  editor,
}: {
  plugin: CodeEditorPlugin;
  editor: CodeEditorInstance;
}) {
  plugin.setup?.(editor);
  return null;
}

/** The editor from the nearest CodeEditor or CodeEditorRoot. */
export function useCodeEditorContext() {
  const editor = useContext(CodeEditorContext);
  if (!editor)
    throw new Error("CodeEditor parts must render inside CodeEditor");
  return editor;
}

export type CodeEditorLanguageOption = { value: string; label: string };

const LANGUAGE_NAMES: Readonly<Record<string, string>> = {
  plaintext: "Plain text",
  css: "CSS",
  go: "Go",
  html: "HTML",
  java: "Java",
  javascript: "JavaScript",
  json: "JSON",
  markdown: "Markdown",
  python: "Python",
  rust: "Rust",
  shell: "Shell",
  sql: "SQL",
  tsx: "TSX",
  typescript: "TypeScript",
  yaml: "YAML",
};

export const codeEditorLanguages: readonly CodeEditorLanguageOption[] =
  Object.entries(LANGUAGE_NAMES).map(([value, label]) => ({ value, label }));

/** Maps aliases such as `ts` or `md` to Monaco language ids. */
export function normalizeLanguage(value: string) {
  const id = value.trim().toLowerCase();
  if (!id) return "plaintext";
  switch (id) {
    case "ts":
      return "typescript";
    case "js":
      return "javascript";
    case "md":
      return "markdown";
    case "text":
      return "plaintext";
    default:
      return id;
  }
}

export function languageLabel(value: string) {
  if (Object.hasOwn(LANGUAGE_NAMES, value)) return LANGUAGE_NAMES[value];
  return value;
}

import type { CodeEditorPlugin } from "@/components/ui/code-editor/types";
import { copy, fullscreen } from "@/components/ui/code-editor/plugins/toolbar-buttons";

export {
  type LanguageSelectOptions,
  languageSelect,
} from "@/components/ui/code-editor/plugins/language-select";
export { type PreviewOptions, preview } from "@/components/ui/code-editor/plugins/preview";
export { copy, format, fullscreen } from "@/components/ui/code-editor/plugins/toolbar-buttons";

/** Copy and fullscreen. Spread more plugins before or after it. */
export function defaultPlugins(): CodeEditorPlugin[] {
  return [copy(), fullscreen()];
}

"use client";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectList,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useCodeEditorContext } from "@/components/ui/code-editor/context";
import {
  type CodeEditorLanguageOption,
  codeEditorLanguages,
  languageLabel,
  normalizeLanguage,
} from "@/components/ui/code-editor/languages";
import type { CodeEditorPlugin } from "@/components/ui/code-editor/types";

export interface LanguageSelectOptions {
  readonly onChange: (language: string) => void;
  readonly languages?: readonly CodeEditorLanguageOption[];
}

function LanguageSelect({
  onChange,
  languages,
}: Readonly<Required<LanguageSelectOptions>>) {
  const editor = useCodeEditorContext();
  const options = new Map<string, string>();
  for (const option of languages) {
    const value = normalizeLanguage(option.value);
    if (!options.has(value)) options.set(value, option.label);
  }
  if (!options.has(editor.language))
    options.set(editor.language, languageLabel(editor.language));
  return (
    <Select
      value={editor.language}
      disabled={editor.disabled || options.size < 2}
      items={[...options].map(([value, label]) => ({ value, label }))}
      onValueChange={(next) => {
        if (next !== null && next !== editor.language) onChange(next);
      }}
    >
      <SelectTrigger
        type="button"
        size="sm"
        aria-label={editor.labels.language}
        className="w-fit max-w-36 bg-transparent text-muted-foreground"
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectList>
          {[...options].map(([value, label]) => (
            <SelectItem key={value} value={value}>
              {label}
            </SelectItem>
          ))}
        </SelectList>
      </SelectContent>
    </Select>
  );
}

/** A language picker. The parent owns `language` and updates it in `onChange`. */
export function languageSelect({
  onChange,
  languages = codeEditorLanguages,
}: LanguageSelectOptions): CodeEditorPlugin {
  return {
    name: "languageSelect",
    toolbar: () => <LanguageSelect onChange={onChange} languages={languages} />,
  };
}

"use client";

import { Columns2, Eye, EyeOff } from "lucide-react";
import { useCodeEditorContext } from "@/components/ui/code-editor/context";
import { CodeEditorToolbarButton } from "@/components/ui/code-editor/toolbar";
import type { CodeEditorPlugin, CodeEditorPreviewConfig } from "@/components/ui/code-editor/types";

export interface PreviewOptions extends CodeEditorPreviewConfig {
  /** Show the preview and split toggles. Defaults to true. */
  readonly toggles?: boolean;
}

function PreviewToggles() {
  const editor = useCodeEditorContext();
  const previewing = editor.mode === "preview";
  return (
    <>
      <CodeEditorToolbarButton
        variant={previewing ? "secondary" : "ghost"}
        tooltip={previewing ? editor.labels.hidePreview : editor.labels.preview}
        onClick={() => editor.setMode(previewing ? "edit" : "preview")}
      >
        {previewing ? <EyeOff /> : <Eye />}
      </CodeEditorToolbarButton>
      <CodeEditorToolbarButton
        variant={editor.isSplitView ? "secondary" : "ghost"}
        tooltip={editor.labels.split}
        onClick={() =>
          editor.setMode(editor.mode === "split" ? "edit" : "split")
        }
      >
        <Columns2 />
      </CodeEditorToolbarButton>
    </>
  );
}

/**
 * A preview pane next to or instead of the editor. CodeEditor has no
 * built-in renderers: `render` returns any component, such as
 * `<MarkdownViewer content={value} />`. Scroll sync follows the pane, or
 * the element passed to `context.setScrollElement`.
 */
export function preview({
  toggles = true,
  ...config
}: PreviewOptions): CodeEditorPlugin {
  return {
    name: "preview",
    preview: config,
    toolbar: toggles ? () => <PreviewToggles /> : undefined,
  };
}

"use client";

import { cn } from "cn";
import { Maximize2, Minimize2, WandSparkles } from "lucide-react";
import { useClipboard } from "@/hooks/use-clipboard";
import { CopyIcon } from "@/components/ui/copy-icon";
import { useCodeEditorContext } from "@/components/ui/code-editor/context";
import { CodeEditorToolbarButton } from "@/components/ui/code-editor/toolbar";
import type { CodeEditorFullscreenConfig, CodeEditorPlugin } from "@/components/ui/code-editor/types";

function CopyButton() {
  const editor = useCodeEditorContext();
  const { status, copy } = useClipboard(editor.value);
  let tooltip = editor.labels.copy;
  if (status === "copied") tooltip = editor.labels.copied;
  else if (status === "error") tooltip = editor.labels.copyFailed;
  return (
    <CodeEditorToolbarButton
      tooltip={tooltip}
      disabled={editor.disabled || status === "pending"}
      onClick={() => void copy(editor.value)}
    >
      <CopyIcon
        status={status}
        className={cn(
          status === "copied" && "text-primary",
          status === "error" && "text-destructive",
        )}
      />
    </CodeEditorToolbarButton>
  );
}

/** A toolbar button that copies the current value. */
export function copy(): CodeEditorPlugin {
  return { name: "copy", toolbar: () => <CopyButton /> };
}

function FormatButton() {
  const editor = useCodeEditorContext();
  return (
    <CodeEditorToolbarButton
      tooltip={editor.labels.format}
      disabled={editor.disabled}
      onClick={editor.format}
    >
      <WandSparkles />
    </CodeEditorToolbarButton>
  );
}

/** A toolbar button that runs Monaco's document formatter. */
export function format(): CodeEditorPlugin {
  return { name: "format", toolbar: () => <FormatButton /> };
}

function FullscreenButton() {
  const editor = useCodeEditorContext();
  return (
    <CodeEditorToolbarButton
      tooltip={
        editor.fullscreen
          ? editor.labels.exitFullscreen
          : editor.labels.fullscreen
      }
      onClick={() => editor.setFullscreen(!editor.fullscreen)}
    >
      {editor.fullscreen ? <Minimize2 /> : <Maximize2 />}
    </CodeEditorToolbarButton>
  );
}

/**
 * A fullscreen toggle. `fixed` covers the viewport inside the page;
 * `screen` uses the browser Fullscreen API.
 */
export function fullscreen(
  options: CodeEditorFullscreenConfig = {},
): CodeEditorPlugin {
  return {
    name: "fullscreen",
    fullscreen: options,
    toolbar: () => <FullscreenButton />,
  };
}

"use client";

import { cn } from "cn";
import type { ReactNode } from "react";
import { CodeEditorProvider } from "@/components/ui/code-editor/context";
import type { CodeEditorInstance } from "@/components/ui/code-editor/types";

export interface CodeEditorRootProps {
  readonly editor: CodeEditorInstance;
  readonly className?: string;
  readonly children?: ReactNode;
}

/** The surface and fullscreen container. Parts read `editor` from context. */
export function CodeEditorRoot({
  editor,
  className,
  children,
}: Readonly<CodeEditorRootProps>) {
  const { internal, labels } = editor;
  return (
    <CodeEditorProvider editor={editor}>
      <div
        data-slot="code-editor"
        {...(internal.fixedFullscreen
          ? {
              role: "dialog",
              "aria-modal": true,
              "aria-label": labels.fullscreen,
            }
          : {})}
        ref={internal.rootRef}
        className={cn(
          "min-h-0 w-full min-w-0",
          internal.fillsParent && "h-full",
          internal.screenFullscreen && "bg-background",
          className,
        )}
        style={internal.rootStyle}
      >
        <div
          data-slot="code-editor-surface"
          className={cn(
            "flex min-h-0 w-full flex-col overflow-hidden rounded-2xl bg-muted/80 text-foreground text-sm ring-1 ring-foreground/5 dark:ring-foreground/10",
            internal.fillsParent && "h-full min-h-0",
            internal.fixedFullscreen &&
              "fixed inset-0 z-50 h-full rounded-none border-0",
            internal.screenFullscreen && "h-screen rounded-none border-0",
          )}
        >
          {children}
        </div>
      </div>
    </CodeEditorProvider>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import type { MonacoEditorInstance } from "@/components/ui/code-editor/types";

function maxScrollTop(element: HTMLElement) {
  return Math.max(element.scrollHeight - element.clientHeight, 0);
}

function editorMaxScrollTop(editor: MonacoEditorInstance) {
  return Math.max(editor.getScrollHeight() - editor.getLayoutInfo().height, 0);
}

/** Keeps the editor and preview at the same relative scroll position. */
export function usePreviewScrollSync() {
  const previewPaneRef = useRef<HTMLDivElement | null>(null);
  const scrollElementRef = useRef<HTMLElement | null>(null);
  const editorRef = useRef<MonacoEditorInstance | null>(null);
  const disposableRef = useRef<{ dispose: () => void } | null>(null);
  const sourceRef = useRef<"editor" | "preview" | null>(null);
  const enabledRef = useRef(false);

  const releaseLock = useCallback(() => {
    window.requestAnimationFrame(() => {
      sourceRef.current = null;
    });
  }, []);

  const syncFromEditor = useCallback(
    (editor: MonacoEditorInstance) => {
      if (!enabledRef.current || sourceRef.current === "preview") return;
      const preview = scrollElementRef.current ?? previewPaneRef.current;
      if (!preview) return;
      const editorMax = editorMaxScrollTop(editor);
      const previewMax = maxScrollTop(preview);
      if (editorMax <= 0 || previewMax <= 0) return;
      sourceRef.current = "editor";
      preview.scrollTop = (editor.getScrollTop() / editorMax) * previewMax;
      releaseLock();
    },
    [releaseLock],
  );

  const syncFromPreview = useCallback(
    (preview: HTMLElement) => {
      const editor = editorRef.current;
      if (!enabledRef.current || sourceRef.current === "editor" || !editor)
        return;
      const previewMax = maxScrollTop(preview);
      const editorMax = editorMaxScrollTop(editor);
      if (previewMax <= 0 || editorMax <= 0) return;
      sourceRef.current = "preview";
      editor.setScrollTop((preview.scrollTop / previewMax) * editorMax);
      releaseLock();
    },
    [releaseLock],
  );

  const attach = useCallback(
    (editor: MonacoEditorInstance) => {
      editorRef.current = editor;
      disposableRef.current?.dispose();
      disposableRef.current = editor.onDidScrollChange(() =>
        syncFromEditor(editor),
      );
    },
    [syncFromEditor],
  );

  const setScrollElement = useCallback((element: HTMLElement | null) => {
    scrollElementRef.current = element;
  }, []);

  const setEnabled = useCallback((enabled: boolean) => {
    enabledRef.current = enabled;
  }, []);

  useEffect(() => () => disposableRef.current?.dispose(), []);

  return {
    previewPaneRef,
    editorRef,
    attach,
    setScrollElement,
    syncFromPreview,
    setEnabled,
  };
}

"use client";

import { cn } from "cn";
import { FileCode2 } from "lucide-react";
import { type ComponentProps, Fragment, type ReactNode } from "react";
import { ViewerButton } from "@/components/ui/viewer/controls";
import { useCodeEditorContext } from "@/components/ui/code-editor/context";
import { languageLabel } from "@/components/ui/code-editor/languages";

export function CodeEditorToolbarButton({
  size,
  variant = "ghost",
  className,
  ...props
}: Readonly<ComponentProps<typeof ViewerButton>>) {
  const editor = useCodeEditorContext();
  return (
    <ViewerButton
      size={size ?? editor.size}
      variant={variant}
      className={cn(
        "text-muted-foreground hover:bg-background/70 hover:text-foreground [&_svg]:size-3.5",
        className,
      )}
      {...props}
    />
  );
}

/** The file icon and title. Defaults to the language name. */
export function CodeEditorTitle({
  className,
  children,
}: Readonly<{ className?: string; children?: ReactNode }>) {
  const editor = useCodeEditorContext();
  return (
    <>
      <FileCode2
        aria-hidden="true"
        className="size-3.5 shrink-0 text-muted-foreground/70"
      />
      <span
        className={cn(
          "min-w-20 flex-1 truncate font-medium font-mono text-foreground/80 text-sm",
          className,
        )}
      >
        {children ?? languageLabel(editor.language)}
      </span>
    </>
  );
}

/** Children first, then each plugin's toolbar item in plugin order. */
export function CodeEditorActions({
  className,
  children,
}: Readonly<{ className?: string; children?: ReactNode }>) {
  const editor = useCodeEditorContext();
  return (
    <div
      className={cn(
        "ml-auto flex shrink-0 flex-wrap items-center justify-end gap-1",
        className,
      )}
    >
      {children}
      {editor.plugins.map(
        (plugin) =>
          plugin.toolbar && (
            <Fragment key={plugin.name}>{plugin.toolbar(editor)}</Fragment>
          ),
      )}
    </div>
  );
}

export interface CodeEditorToolbarProps {
  readonly className?: string;
  /** Replaces the default title and actions. */
  readonly children?: ReactNode;
}

export function CodeEditorToolbar({
  className,
  children,
}: Readonly<CodeEditorToolbarProps>) {
  return (
    <div
      data-slot="code-editor-toolbar"
      className={cn(
        "flex min-h-10 shrink-0 flex-wrap items-center gap-x-2 gap-y-1 border-b bg-muted/80 px-3 py-1",
        className,
      )}
    >
      {children ?? (
        <>
          <CodeEditorTitle />
          <CodeEditorActions />
        </>
      )}
    </div>
  );
}

import type { Monaco } from "@monaco-editor/react";
import type { editor } from "monaco-editor";
import type { ComponentProps, ReactNode, RefObject } from "react";
import type { ViewerThemes } from "@/lib/viewer/shiki";
import type { Button } from "@/components/ui/button";
import type { CodeEditorLabels } from "@/components/ui/code-editor/labels";

export type CodeEditorTheme = "light" | "dark";
export type CodeEditorViewMode = "edit" | "preview" | "split";
export type CodeEditorFullscreenMode = "fixed" | "screen";
export type CodeEditorButtonSize = ComponentProps<typeof Button>["size"];
export type MonacoEditorInstance = editor.IStandaloneCodeEditor;
export type MonacoEditorOptions = editor.IStandaloneEditorConstructionOptions;

/** What a preview renderer receives besides the current value. */
export interface CodeEditorPreviewContext {
  readonly language: string;
  /**
   * Point scroll sync at an element other than the preview pane, such as
   * the document inside an iframe. Pass `null` to fall back to the pane.
   */
  setScrollElement(element: HTMLElement | null): void;
  /** Report a scroll of that element so the editor follows it. */
  syncFromPreview(element: HTMLElement): void;
}

export interface CodeEditorPreviewConfig {
  readonly render: (
    value: string,
    context: CodeEditorPreviewContext,
  ) => ReactNode;
  readonly mode?: CodeEditorViewMode;
  readonly defaultMode?: CodeEditorViewMode;
  readonly onModeChange?: (mode: CodeEditorViewMode) => void;
}

export interface CodeEditorFullscreenConfig {
  readonly mode?: CodeEditorFullscreenMode;
  readonly value?: boolean;
  readonly defaultValue?: boolean;
  readonly onChange?: (fullscreen: boolean) => void;
}

/**
 * Features beyond editing are plugins. `toolbar` renders in the toolbar's
 * action area in plugin order; `setup` runs as a hook under the provider.
 */
export interface CodeEditorPlugin {
  readonly name: string;
  readonly preview?: CodeEditorPreviewConfig;
  readonly fullscreen?: CodeEditorFullscreenConfig;
  readonly options?: MonacoEditorOptions;
  readonly toolbar?: (editor: CodeEditorInstance) => ReactNode;
  readonly setup?: (editor: CodeEditorInstance) => void;
}

export interface CodeEditorInstance {
  readonly value: string;
  readonly language: string;
  readonly disabled: boolean;
  readonly theme: CodeEditorTheme;
  readonly size: CodeEditorButtonSize;
  readonly labels: CodeEditorLabels;
  readonly plugins: readonly CodeEditorPlugin[];
  readonly mode: CodeEditorViewMode;
  readonly hasPreview: boolean;
  readonly isSplitView: boolean;
  readonly fullscreen: boolean;
  readonly fullscreenMode: CodeEditorFullscreenMode;
  /** The Monaco instance once it has mounted. */
  readonly editor: MonacoEditorInstance | null;
  hasPlugin(name: string): boolean;
  setValue(value: string): void;
  setMode(mode: CodeEditorViewMode): void;
  setFullscreen(fullscreen: boolean): void;
  format(): void;
  /** Internal wiring for CodeEditorRoot and CodeEditorContent. */
  readonly internal: CodeEditorInternal;
}

export interface CodeEditorInternal {
  readonly rootRef: RefObject<HTMLDivElement | null>;
  readonly rootStyle: { height: string | undefined } | undefined;
  readonly contentStyle: { height: string | undefined } | undefined;
  readonly fillsParent: boolean;
  readonly fixedFullscreen: boolean;
  readonly screenFullscreen: boolean;
  readonly showEditorPane: boolean;
  readonly showPreviewPane: boolean;
  readonly preview: CodeEditorPreviewConfig | undefined;
  readonly previewContext: CodeEditorPreviewContext;
  readonly previewPaneRef: RefObject<HTMLDivElement | null>;
  readonly onPreviewScroll: (element: HTMLElement) => void;
  readonly modelPath: string;
  readonly themeName: string;
  readonly shikiThemes: ViewerThemes;
  readonly options: MonacoEditorOptions;
  readonly onMount: (editor: MonacoEditorInstance, monaco: Monaco) => void;
  readonly onChange: (value: string) => void;
}

"use client";

import type { Monaco } from "@monaco-editor/react";
import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { useFullscreen } from "@/hooks/use-fullscreen";
import { useViewerTheme } from "@/hooks/use-viewer-theme";
import type { ViewerThemes } from "@/lib/viewer/shiki";
import { useShikiThemes } from "@/lib/viewer/shiki-context";
import { type CodeEditorLabelOverrides, codeEditorLabels } from "@/components/ui/code-editor/labels";
import { normalizeLanguage } from "@/components/ui/code-editor/languages";
import { usePreviewScrollSync } from "@/components/ui/code-editor/scroll-sync";
import type {
  CodeEditorButtonSize,
  CodeEditorInstance,
  CodeEditorPlugin,
  CodeEditorPreviewContext,
  CodeEditorTheme,
  CodeEditorViewMode,
  MonacoEditorInstance,
  MonacoEditorOptions,
} from "@/components/ui/code-editor/types";

export interface UseCodeEditorOptions {
  readonly value?: string;
  readonly defaultValue?: string;
  readonly onChange?: (value: string) => void;
  readonly language?: string;
  readonly disabled?: boolean;
  /** Content height. Without it the editor fills its parent. */
  readonly height?: string | number;
  readonly size?: CodeEditorButtonSize;
  readonly labels?: CodeEditorLabelOverrides;
  readonly plugins?: readonly CodeEditorPlugin[];
  /** Monaco options, merged over the defaults and plugin options. */
  readonly options?: MonacoEditorOptions;
}

const NO_PLUGINS: readonly CodeEditorPlugin[] = [];
let nextModelId = 0;

const defaultOptions: MonacoEditorOptions = {
  minimap: { enabled: false },
  fontSize: 14,
  lineNumbers: "on",
  roundedSelection: false,
  scrollBeyondLastLine: false,
  scrollbar: {
    vertical: "auto",
    horizontal: "auto",
    useShadows: false,
    verticalScrollbarSize: 10,
    horizontalScrollbarSize: 10,
  },
  automaticLayout: true,
  padding: { top: 8, bottom: 8 },
};

async function applyShikiTheme(
  monaco: Monaco,
  theme: CodeEditorTheme,
  element: HTMLElement,
  name: string,
  isCurrent: () => boolean,
  language: string,
  themes: ViewerThemes,
) {
  const { applyEditorTheme } = await import("@/lib/editor/monaco-theme");
  await applyEditorTheme(
    monaco,
    theme,
    element,
    name,
    isCurrent,
    language,
    themes,
  );
}

function useEditorValue(
  value: string | undefined,
  defaultValue: string,
  onChange: ((value: string) => void) | undefined,
  disabled: boolean,
) {
  const [localValue, setLocalValue] = useState(value ?? defaultValue);
  useEffect(() => {
    if (value !== undefined) setLocalValue(value);
  }, [value]);
  const setValue = useCallback(
    (next: string) => {
      if (disabled) return;
      if (value === undefined) setLocalValue(next);
      onChange?.(next);
    },
    [disabled, onChange, value],
  );
  return [value ?? localValue, setValue] as const;
}

function useModelPath(language: string) {
  // Monaco keeps models process-wide by URI, including across separate React roots.
  // The path is only rendered after mount, so a client-local ID is sufficient.
  const [id] = useState(() => ++nextModelId);
  let extension = language;
  if (language === "typescript") extension = "ts";
  else if (language === "javascript") extension = "jsx";
  return `file:///code-editor-${id}/index.${extension}`;
}

/** Follows the nearest `.dark` ancestor, so scoped dark sections work. */
function useScopedTheme(element: { current: HTMLElement | null }) {
  const [localDark, setLocalDark] = useState(false);
  const { resolvedTheme } = useViewerTheme();
  useEffect(() => {
    const node = element.current;
    if (!node) return;
    const resolve = () => setLocalDark(node.closest(".dark") !== null);
    resolve();
    const observer = new MutationObserver(resolve);
    for (
      let ancestor: HTMLElement | null = node;
      ancestor;
      ancestor = ancestor.parentElement
    )
      observer.observe(ancestor, {
        attributes: true,
        attributeFilter: ["class"],
      });
    return () => observer.disconnect();
  }, [element]);
  const theme: CodeEditorTheme = localDark ? "dark" : resolvedTheme;
  return theme;
}

function cssSize(height: string | number | undefined) {
  if (typeof height === "number") return `${height}px`;
  return height;
}

export function useCodeEditor({
  value: controlledValue,
  defaultValue = "",
  onChange,
  language: requestedLanguage = "plaintext",
  disabled = false,
  height,
  size = "icon-sm",
  labels: labelOverrides,
  plugins = NO_PLUGINS,
  options,
}: UseCodeEditorOptions = {}): CodeEditorInstance {
  const language = normalizeLanguage(requestedLanguage);
  const labels = useMemo(
    () => ({ ...codeEditorLabels, ...labelOverrides }),
    [labelOverrides],
  );
  const [value, setValue] = useEditorValue(
    controlledValue,
    defaultValue,
    onChange,
    disabled,
  );
  const modelPath = useModelPath(language);
  // Keep the registered name stable while the async Shiki theme is rebuilt.
  // Monaco's React wrapper applies a changed `theme` prop synchronously.
  const themeName = `code-editor-${useId()
    .replace(/[^a-zA-Z0-9-]/g, "")
    .toLowerCase()}`;
  const shikiThemes = useShikiThemes();
  const rootRef = useRef<HTMLDivElement>(null);
  const theme = useScopedTheme(rootRef);

  const previewConfig = plugins.find((plugin) => plugin.preview)?.preview;
  const fullscreenConfig = plugins.find(
    (plugin) => plugin.fullscreen,
  )?.fullscreen;

  // View mode
  const hasPreview = previewConfig !== undefined;
  const [uncontrolledMode, setUncontrolledMode] = useState<CodeEditorViewMode>(
    () => {
      if (!previewConfig) return "edit";
      return previewConfig.defaultMode ?? "split";
    },
  );
  let mode: CodeEditorViewMode = "edit";
  if (hasPreview) mode = previewConfig.mode ?? uncontrolledMode;
  const controlledMode = previewConfig?.mode;
  const onModeChange = previewConfig?.onModeChange;
  const setMode = useCallback(
    (next: CodeEditorViewMode) => {
      const resolved = hasPreview ? next : "edit";
      if (controlledMode === undefined) setUncontrolledMode(resolved);
      onModeChange?.(resolved);
    },
    [controlledMode, hasPreview, onModeChange],
  );
  const showEditorPane = mode !== "preview";
  const showPreviewPane = hasPreview && mode !== "edit";
  const isSplitView = showEditorPane && showPreviewPane;

  // Fullscreen
  const fullscreenMode = fullscreenConfig?.mode ?? "fixed";
  const fullscreenState = useFullscreen({
    fullscreen: fullscreenConfig?.value,
    defaultFullscreen: fullscreenConfig?.defaultValue,
    onFullscreenChange: fullscreenConfig?.onChange,
    mode: fullscreenMode,
    ref: rootRef,
  });
  const fullscreen = fullscreenState.fullscreen;
  const hasHeight = height !== undefined;
  const contentHeight = cssSize(height);
  const fixedFullscreen = fullscreen && fullscreenMode === "fixed";

  // Monaco
  const scroll = usePreviewScrollSync();
  const [monacoEditor, setMonacoEditor] = useState<MonacoEditorInstance | null>(
    null,
  );
  const monacoRef = useRef<Monaco | null>(null);
  const themeRef = useRef({ theme, name: themeName });
  const themeGeneration = useRef(0);

  useEffect(() => {
    themeRef.current = { theme, name: themeName };
  }, [theme, themeName]);

  useEffect(() => {
    scroll.setEnabled(isSplitView);
  }, [isSplitView, scroll.setEnabled]);

  useEffect(
    () => () => {
      themeGeneration.current++;
    },
    [],
  );

  const updateTheme = useCallback(
    (monaco: Monaco, nextTheme: CodeEditorTheme, name: string) => {
      const element = rootRef.current;
      if (!element) return;
      const generation = ++themeGeneration.current;
      applyShikiTheme(
        monaco,
        nextTheme,
        element,
        name,
        () =>
          themeGeneration.current === generation &&
          rootRef.current === element &&
          element.isConnected,
        language,
        shikiThemes,
      ).catch(() => {});
    },
    [language, shikiThemes],
  );

  useEffect(() => {
    const monaco = monacoRef.current;
    if (monaco) updateTheme(monaco, theme, themeName);
  }, [theme, themeName, updateTheme]);

  const onMount = useCallback(
    (instance: MonacoEditorInstance, monaco: Monaco) => {
      setMonacoEditor(instance);
      monacoRef.current = monaco;
      scroll.attach(instance);
      const current = themeRef.current;
      updateTheme(monaco, current.theme, current.name);
    },
    [scroll.attach, updateTheme],
  );

  const format = useCallback(() => {
    if (disabled) return;
    scroll.editorRef.current?.getAction("editor.action.formatDocument")?.run();
  }, [disabled, scroll.editorRef]);

  // Stable options, so Monaco does not re-apply them on every keystroke.
  // Memoize the plugin list for the same reason.
  const monacoOptions = useMemo<MonacoEditorOptions>(
    () =>
      Object.assign(
        {},
        defaultOptions,
        ...plugins.map((plugin) => plugin.options),
        options,
        { readOnly: disabled, domReadOnly: disabled },
      ),
    [disabled, options, plugins],
  );

  const previewContext = useMemo<CodeEditorPreviewContext>(
    () => ({
      language,
      setScrollElement: scroll.setScrollElement,
      syncFromPreview: scroll.syncFromPreview,
    }),
    [language, scroll.setScrollElement, scroll.syncFromPreview],
  );

  return {
    value,
    language,
    disabled,
    theme,
    size,
    labels,
    plugins,
    mode,
    hasPreview,
    isSplitView,
    fullscreen,
    fullscreenMode,
    editor: monacoEditor,
    hasPlugin: (name) => plugins.some((plugin) => plugin.name === name),
    setValue,
    setMode,
    setFullscreen: fullscreenState.setFullscreen,
    format,
    internal: {
      rootRef,
      rootStyle:
        fixedFullscreen && hasHeight ? { height: contentHeight } : undefined,
      contentStyle:
        hasHeight && !fullscreen ? { height: contentHeight } : undefined,
      fillsParent: fullscreen || !hasHeight,
      fixedFullscreen,
      screenFullscreen: fullscreen && fullscreenMode === "screen",
      showEditorPane,
      showPreviewPane,
      preview: previewConfig,
      previewContext,
      previewPaneRef: scroll.previewPaneRef,
      onPreviewScroll: scroll.syncFromPreview,
      modelPath,
      themeName,
      shikiThemes,
      options: monacoOptions,
      onMount,
      onChange: setValue,
    },
  };
}

