const loadedLanguages = new Map<string, Promise<void>>();
const loadedThemes = new Map<BundledTheme, Promise<void>>();
export async function getViewerHighlighter(
  language: string,
  theme: "light" | "dark",
  themes: ViewerThemes = defaultViewerThemes,
